// 4. [T=2] While L1 state is stale, attacker calls Vault.requestRedeem() for a large amount. USDM moves to Vault but is not burned; USDC is not yet in RedeemEscrow. totalBackingSigned() now counts both the stale L1 backing AND the phantom surplus from the pending redemption.
// 5. [T=365 days] After a prolonged settlement gap, operator calls settleDailyPnL. The annualized yield cap is unbounded due to elapsed time. The entire doubly-inflated phantom surplus passes Gate 4 and is declared as distributable yield.
// 6. [Assert] Verify that the accountant recorded a massive phantom yield distribution, proving the unbounded yield cap exploit.

interface IMockERC20 {
    function mint(address to, uint256 amount) external;
    function approve(address spender, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

contract MockUSDC {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract MockHyperCore {
    uint64 public spotBalance;

    function setSpotBalance(uint64 _bal) external {
        spotBalance = _bal;
    }

    // Mocking the precompile read for L1 backing
    function querySpotBalance(address, uint64) external view returns (uint64) {
        return spotBalance;
    }
}

