        uint256 depositAmount = 1_000_000 * 1e6; // 1M USDM (assuming 6 decimals)

        vm.startPrank(governor);
        usdm.mint(whale, depositAmount);
        vm.stopPrank();

        vm.startPrank(whale);
        usdm.approve(address(susdm), depositAmount);
        susdm.deposit(depositAmount, whale);
        vm.stopPrank();

        uint256 totalSupply = usdm.totalSupply();
        uint256 maxAnnualYieldBps = config.maxAnnualYieldBps();

        // Fair daily cap (1 day)
        uint256 fairDailyCap = (totalSupply * maxAnnualYieldBps * 1 days) / (10_000 * 365 days);

        // 2. Warp 30 days into the future to simulate settlement gap
        vm.warp(block.timestamp + 30 days);

        // 3. Calculate the inflated single-shot cap (30 days)
        // Gate 4 cap = (totalSupply * maxAnnualYieldBps * elapsed) / (10_000 * 365 days)
        uint256 singleShotCap = (totalSupply * maxAnnualYieldBps * 30 days) / (10_000 * 365 days);

        // 4. Assert the vulnerability: Gate 4 allows outsized single-shot yield extraction after long gaps
        // The cap scales linearly with time, meaning a 30-day gap allows extracting 30 days worth of yield in one tx
        assertGt(singleShotCap, fairDailyCap * 29, "Gate 4 allows outsized single-shot yield extraction after long gaps");

        // Additional check: The single shot cap is approximately 8.2% of total supply (if maxAnnualYieldBps is 1000)
        // 1000 bps = 10% annual. 30/365 * 10% = 0.82% of total supply.
        // If maxAnnualYieldBps is higher, the percentage is higher.
        uint256 expectedCapFor30Days = (totalSupply * maxAnnualYieldBps * 30) / (10_000 * 365);
        assertEq(singleShotCap, expectedCapFor30Days, "Cap calculation matches linear time scaling");
    }
}

