// 3. [T=1] A massive yield (e.g., 10,000 USDC) accumulates in the YieldEscrow.
// 4. [T=2] Operator calls vault.distributeYield().
// 5. [T=2] Vault pulls the FULL 10,000 USDC from YieldEscrow.
// 6. [T=2] Vault computes userShare (70% = 7,000 USDC) and calls susdm.injectYield(7000).
// 7. [T=2] sUSDM reverts because 7,000 > 1,000 (maxYieldPerInjection).
// 8. [Assert] The entire distributeYield transaction reverts. YieldEscrow balance remains 10,000 USDC.
// 9. [Assert] Subsequent calls will also revert because the balance only grows or stays the same, permanently DoSing yield distribution.

contract AuditAgentPoC is Test {
    MonetrixAccessController acl;
    MonetrixConfig config;
    USDM usdm;
    sUSDM susdm;
    YieldEscrow yieldEscrow;
    MonetrixVault vault;

    address admin = address(0xAD);
    address operator = address(0x0P);
    address user1 = address(0x1);
    address foundation = address(0xF);
    address insuranceFund = address(0x1F);

    // Mock USDC for testing (since we need an ERC20 with mint/balanceOf)
    MockERC20 usdc;

    function setUp() public {
        // 1. Deploy Mock USDC
        usdc = new MockERC20("USD Coin", "USDC", 6);

        // 2. Deploy ACL
        acl = new MonetrixAccessController();
        acl.initialize(admin);

        // Grant roles (assuming standard OpenZeppelin AccessControl roles)
        bytes32 GOVERNOR_ROLE = keccak256("GOVERNOR_ROLE");
        bytes32 OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
        bytes32 GUARDIAN_ROLE = keccak256("GUARDIAN_ROLE");

        vm.startPrank(admin);
        acl.grantRole(GOVERNOR_ROLE, admin);
        acl.grantRole(OPERATOR_ROLE, operator);
        acl.grantRole(GUARDIAN_ROLE, admin);
        vm.stopPrank();

        // 3. Deploy Config
        config = new MonetrixConfig();
        config.initialize(insuranceFund, foundation, address(acl));

        // 4. Deploy USDM
        usdm = new USDM();
        usdm.initialize(address(acl));

        // 5. Deploy sUSDM
        susdm = new sUSDM();
        susdm.initialize(address(usdm), address(config), address(acl));

        // 6. Deploy YieldEscrow
        yieldEscrow = new YieldEscrow();
        // Note: YieldEscrow constructor in interface is `can()` but we use the actual contract name
        // The interface says: contract can { constructor(); function initialize(...) }
        // We'll assume the actual contract is named YieldEscrow and has initialize

        // 7. Deploy Vault
        vault = new MonetrixVault();
        vault.initialize(
            address(usdc),
            address(usdm),
            address(susdm),
            address(config),
            address(this), // coreDepositWallet
            address(acl)
        );

        // 8. Wire contracts
        vm.startPrank(admin);
        usdm.setVault(address(vault));
        susdm.setVault(address(vault));
        yieldEscrow.initialize(address(usdc), address(vault), address(acl));
        vault.setYieldEscrow(address(yieldEscrow));

        // Set a low max yield cap to trigger the DoS
        config.setMaxYieldPerInjection(1_000e6); // 1,000 USDC cap

        // Set yield bps (70% user, 10% insurance, 20% foundation)
        config.setYieldBps(7000, 1000);
        vm.stopPrank();

        // 9. Fund YieldEscrow with massive yield (10,000 USDC)
        usdc.mint(address(yieldEscrow), 10_000e6);
    }

    function test_exploit() public {
        uint256 escrowBalanceBefore = usdc.balanceOf(address(yieldEscrow));
        assertEq(escrowBalanceBefore, 10_000e6, "YieldEscrow should have 10,000 USDC");

        // Operator attempts to distribute yield
        vm.prank(operator);
        vm.expectRevert("sUSDM: yield exceeds max");
        vault.distributeYield();

        // Assert that the YieldEscrow balance is unchanged (DoS confirmed)
        uint256 escrowBalanceAfter = usdc.balanceOf(address(yieldEscrow));
        assertEq(escrowBalanceAfter, 10_000e6, "YieldEscrow balance should remain unchanged due to DoS");

        // Assert that sUSDM received no yield
        assertEq(usdm.balanceOf(address(susdm)), 0, "sUSDM should have received no USDM");
    }
}

// Minimal Mock ERC20 for testing since actual USDC isn't provided in src/
contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
        totalSupply += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

